def _finite(v):
    return not math.isnan(v) and not math.isinf(v)

def _validate(p):
    for name, v in {"Module": p.Module, "PressureAngle": p.PressureAngle, "Thickness": p.Thickness, "BoreDiameter": p.BoreDiameter, "CapChamfer": p.CapChamfer}.items():
        if not _finite(v):
            raise RuntimeError("%s must be finite, got %s" % (name, _fx.go_float(v),))
    if p.Module <= 0:
        raise RuntimeError("module %s must be positive" % (_fx.go_float(p.Module),))
    elif p.Thickness <= 0:
        raise RuntimeError("thickness %s must be positive" % (_fx.go_float(p.Thickness),))
    elif p.Teeth < 3:
        raise RuntimeError("teeth %d must be at least 3" % (p.Teeth,))
    elif p.Samples < 3:
        raise RuntimeError("samples %d must be at least 3" % (p.Samples,))
    elif (p.PressureAngle <= 0) or (p.PressureAngle >= (math.pi / 2)):
        raise RuntimeError("pressure angle %s must be in (0, pi/2)" % (_fx.go_float(p.PressureAngle),))
    elif p.BoreDiameter < 0:
        raise RuntimeError("bore diameter %s must not be negative" % (_fx.go_float(p.BoreDiameter),))
    elif p.CapChamfer < 0:
        raise RuntimeError("cap chamfer %s must not be negative" % (_fx.go_float(p.CapChamfer),))
    if (p.Placement is not None) and not p.Placement.is_valid():
        raise RuntimeError("invalid placement frame")
    m, n = p.Module, float(p.Teeth)
    pitch = (m * n) / 2
    base = pitch * math.cos(p.PressureAngle)
    root = ((m * n) - (2.5 * m)) / 2
    tip = ((m * n) + (2 * m)) / 2
    if root <= 0:
        raise RuntimeError("root radius %s must be positive" % (_fx.go_float(root),))
    elif base <= 0:
        raise RuntimeError("base radius %s must be positive" % (_fx.go_float(base),))
    elif tip <= base:
        raise RuntimeError("tip radius %s must exceed base radius %s" % (_fx.go_float(tip), _fx.go_float(base),))
    elif p.BoreDiameter >= (2 * root):
        raise RuntimeError("bore diameter %s must be below the root diameter %s" % (_fx.go_float(p.BoreDiameter), _fx.go_float(2 * root),))
    inv = math.tan(p.PressureAngle) - p.PressureAngle
    fillet = ((0.9 * root) * ((math.pi / n) - (2 * inv))) / 2
    if not _finite(fillet):
        raise RuntimeError("root fillet radius %s is not finite" % (_fx.go_float(fillet),))
    return

def _rotate(x, y, theta):
    sin, cos = math.sin(theta), math.cos(theta)
    return _Point((x * cos) - (y * sin), (x * sin) + (y * cos))

def _involute_point(base, r):
    ratio = base / r
    if ratio > 1:
        ratio = 1
    t = math.tan(math.acos(ratio))
    return base * (math.cos(t) + (t * math.sin(t))), base * (math.sin(t) - (t * math.cos(t)))

def _flank_offset(pitch, base, teeth):
    px, py = _involute_point(base, pitch)
    return (math.pi / (2 * teeth)) - math.atan2(-py, px)

def _sample_flanks(pitch, base, start, tip, teeth, samples, angle):
    beta = _flank_offset(pitch, base, teeth)
    left = [None] * (samples)
    right = [None] * (samples)
    for i in range(0, samples):
        r = start + (((tip - start) * float(i)) / float(samples - 1))
        x, y = _involute_point(base, r)
        l = _rotate(x, -y, beta)
        left[i] = _rotate(l.x, l.y, angle)
        right[i] = _rotate(l.x, -l.y, angle)
    return left, right

def involute_flanks(pitch, base, tip, effectiveTeeth, samples, angle):
    for name, v in {"pitch": pitch, "base": base, "tip": tip, "effectiveTeeth": effectiveTeeth, "angle": angle}.items():
        if math.isnan(v) or math.isinf(v):
            raise RuntimeError("involute flanks: %s must be finite, got %s" % (name, _fx.go_float(v),))
    if base <= 0:
        raise RuntimeError("involute flanks: base radius %s must be positive" % (_fx.go_float(base),))
    elif pitch <= base:
        raise RuntimeError("involute flanks: pitch radius %s must exceed base radius %s" % (_fx.go_float(pitch), _fx.go_float(base),))
    elif tip <= pitch:
        raise RuntimeError("involute flanks: tip radius %s must exceed pitch radius %s" % (_fx.go_float(tip), _fx.go_float(pitch),))
    elif effectiveTeeth <= 0:
        raise RuntimeError("involute flanks: effective teeth %s must be positive" % (_fx.go_float(effectiveTeeth),))
    elif samples < 3:
        raise RuntimeError("involute flanks: samples %d must be at least 3" % (samples,))
    left, right = _sample_flanks(pitch, base, base, tip, effectiveTeeth, samples, angle)
    l = [None] * (len(left))
    r = [None] * (len(right))
    for i in range(len(left)):
        l[i] = [left[i].x, left[i].y]
        r[i] = [right[i].x, right[i].y]
    return l, r

def _root_contact(basePoint, d):
    return _Point((basePoint.x * d.root) / d.base, (basePoint.y * d.root) / d.base)

def _tooth_angle(p, k):
    return ((2 * math.pi) * float(k)) / float(p.Teeth)

def _new_tooth_points(s, d, left, right):
    tp = _ToothPoints()
    tp.right = [None] * (len(right))
    for i, q in enumerate(right):
        tp.right[i] = s.dimension_point(q.x, q.y)
    tp.left = [None] * (len(left))
    for i, q in enumerate(left):
        if i == (len(left) - 1):
            tp.left[i] = s.dimension_arc_end(q.x, q.y)
        else:
            tp.left[i] = s.dimension_point(q.x, q.y)
    tp.leftRootAt = _root_contact(left[0], d)
    tp.rightRootAt = _root_contact(right[0], d)
    tp.leftRoot = s.dimension_arc_end(tp.leftRootAt.x, tp.leftRootAt.y)
    tp.rightRoot = s.dimension_point(tp.rightRootAt.x, tp.rightRootAt.y)
    return tp

def _draw_tooth_flanks(s, tp):
    last = len(tp.right) - 1
    s.create_line(tp.rightRoot, tp.right[0])
    s.create_fit_spline(*tp.right)
    s.create_arc(s.origin(), tp.right[last], tp.left[last])
    s.create_fit_spline(*tp.left)
    s.create_line(tp.left[0], tp.leftRoot)
    return

def _to_world(f, xy):
    return f.origin().add(f.u().scale(xy.x)).add(f.v().scale(xy.y))

def _shifted(f, dist):
    return _fx.r3_new_frame(f.origin().add(f.n().scale(dist)), f.u(), f.v())

def _placement(p):
    if p.Placement is not None:
        return p.Placement
    return _fx.r3_new_frame(_fx.r3_new_vec(0, 0, 0), _fx.r3_new_vec(1, 0, 0), _fx.r3_new_vec(0, 1, 0))

def _single_profile(s, curves):
    profiles = s.profiles()
    if len(profiles) != 1:
        raise RuntimeError("expected 1 profile, got %d" % (len(profiles),))
    profile = profiles[0]
    if not profile.Valid:
        raise RuntimeError("profile is not valid")
    if (curves > 0) and (len(profile.Outer) != curves):
        raise RuntimeError("expected %d outer curves, got %d" % (curves, len(profile.Outer),))
    return profile

def _solve_and_verify(s):
    s.solve()
    _fx.sketchcheck_verify_fully_constrained(s)
    return

def _embedded_closing_radius(p, d):
    beta = _flank_offset(d.pitch, d.base, float(p.Teeth))
    def half(r):
        x, y = _involute_point(d.base, r)
        q = _rotate(x, -y, beta)
        return math.atan2(q.y, q.x)
    limit = math.pi / float(p.Teeth)
    if half(d.base) < limit:
        return d.base
    if half(d.root) >= limit:
        raise RuntimeError("embedded tooth: neighbouring flanks overlap at the root circle (radius %s)" % (_fx.go_float(d.root),))
    lo, hi = d.base, d.root
    for i in range(0, 200):
        mid = (lo + hi) / 2
        if half(mid) >= limit:
            lo = mid
        else:
            hi = mid
    rq = (lo + hi) / 2
    return (rq + d.root) / 2

def _build_root_disc(r):
    s = r.world.create_sketch(r.lower, name="Root Disc Profile")
    circle = s.create_circle(s.origin(), r.d.root)
    radius = _fx.sketch_new_radius(circle, r.d.root)
    s.add_constraint(radius)
    s.bind(radius, r.world.params(), "root_radius")
    _solve_and_verify(s)
    profile = _single_profile(s, 0)
    disc = _fx.decad_extrude(r.doc, s, profile, r.extent, name="Root Disc Extrude", body="Gear Body")
    return disc

def _build_tooth_section(world, plane, p, d, angle):
    s = world.create_sketch(plane, name="Tooth Profile")
    center = s.origin()
    left, right = _sample_flanks(d.pitch, d.base, d.base, d.tip, float(p.Teeth), p.Samples, angle)
    tp = _new_tooth_points(s, d, left, right)
    _draw_tooth_flanks(s, tp)
    s.create_arc(center, tp.rightRoot, tp.leftRoot)
    _solve_and_verify(s)
    profile = _single_profile(s, 6)
    return s, profile

def build_tooth_section(world, plane, p, angle):
    if world is None:
        raise RuntimeError("tooth section: nil world")
    if plane is None:
        raise RuntimeError("tooth section: nil plane")
    _validate(p)
    if math.isnan(angle) or math.isinf(angle):
        raise RuntimeError("tooth section: angle must be finite, got %s" % (_fx.go_float(angle),))
    d = _fx.derive(p)
    if d.root <= 0:
        raise RuntimeError("tooth section: cannot derive gear dimensions")
    if d.base < d.root:
        raise RuntimeError("tooth section: embedded flanks are not supported")
    return _build_tooth_section(world, plane, p, d, angle)

def _build_embedded_tooth(world, plane, p, d):
    rc = _embedded_closing_radius(p, d)
    s = world.create_sketch(plane, name="Tooth Profile")
    center = s.origin()
    left, right = _sample_flanks(d.pitch, d.base, rc, d.tip, float(p.Teeth), p.Samples, 0)
    rp = [None] * (len(right))
    for i, q in enumerate(right):
        rp[i] = s.dimension_point(q.x, q.y)
    lp = [None] * (len(left))
    for i, q in enumerate(left):
        if (i == 0) or (i == (len(left) - 1)):
            lp[i] = s.dimension_arc_end(q.x, q.y)
        else:
            lp[i] = s.dimension_point(q.x, q.y)
    last = len(rp) - 1
    s.create_fit_spline(*rp)
    s.create_arc(center, rp[last], lp[last])
    s.create_fit_spline(*lp)
    s.create_arc(center, rp[0], lp[0])
    _solve_and_verify(s)
    profile = _single_profile(s, 4)
    return s, profile

def tooth_input_shifted(in_, dist):
    return _shifted(in_.Frame, dist.base())

def tooth_input_plane_at(in_, dist):
    f = tooth_input_shifted(in_, dist)
    return in_.World.create_plane_from_frame(f, name="Twisted Section Plane")

def _variant_tooth(v, r):
    if v.Tooth is not None:
        tooth = v.Tooth(_ToothInput(Doc=r.doc, World=r.world, Params=r.p, Frame=r.frame, Lower=r.lower))
        return tooth
    ts = None
    prof = None
    err = None
    if r.d.base < r.d.root:
        ts, prof = _build_embedded_tooth(r.world, r.lower, r.p, r.d)
    else:
        ts, prof = _build_tooth_section(r.world, r.lower, r.p, r.d, 0)
    tooth = _fx.decad_extrude(r.doc, ts, prof, r.extent, name="Tooth Extrude", body="Tooth")
    return tooth

def _fillet_spur_roots(doc, body, r, embedded):
    radius = doc.param("fillet_radius")
    if embedded:
        return _fillet_embedded(body, r.frame, r.teeth, radius)
    roots = []
    left, right = _sample_flanks(r.d.pitch, r.d.base, r.d.base, r.d.tip, float(r.teeth), r.p.Samples, 0)
    for k in range(0, r.teeth):
        a = _tooth_angle(r.p, k)
        rr = _root_contact(right[0], r.d)
        lr = _root_contact(left[0], r.d)
        roots = roots + [_rotate(rr.x, rr.y, a), _rotate(lr.x, lr.y, a)]
    return _fillet_roots_value(body, r.frame, roots, radius)

def _fillet_roots_value(body, frame, roots, radius):
    axis = frame.n()
    edges = _fx.decad_edges(_fx.decad_parallel_to(axis)).select_edges(body)
    corners = []
    for edge in edges:
        start = edge.start().position().Value
        for root in roots:
            if _to_world(frame, root).equal(start, 1e-6):
                corners = corners + [start]
                break
    if len(corners) != len(roots):
        raise RuntimeError("match root edges: matched %d of %d root contacts" % (len(corners), len(roots),))
    if len(corners) == 0:
        raise RuntimeError("match root edges: no root contacts")
    selection = _fx.decad_edges(_fx.decad_parallel_to(axis), _fx.decad_endpoint_at(corners[0]))
    for corner in corners[1:]:
        selection = selection.or_(_fx.decad_parallel_to(axis), _fx.decad_endpoint_at(corner))
    filleted = _fx.decad_fillet(body, selection.exactly(len(corners)), radius, name="Root Fillet")
    return filleted

def _fillet_embedded(body, frame, teeth, radius):
    selection = _fx.decad_edges(_fx.decad_parallel_to(frame.n()), _fx.decad_concave()).exactly(2 * teeth)
    filleted = _fx.decad_fillet(body, selection, radius, name="Root Fillet")
    return filleted

def _build_bore_profile(world, p, margin):
    frame = _placement(p)
    toolFrame = _shifted(frame, -margin)
    plane = world.create_plane_from_frame(toolFrame, name="Bore Tool Plane")
    s = world.create_sketch(plane, name="Bore Profile")
    circle = s.create_circle(s.origin(), p.BoreDiameter / 2)
    diameter = _fx.sketch_new_diameter(circle, p.BoreDiameter)
    s.add_constraint(diameter)
    s.bind(diameter, world.params(), "bore_diameter")
    _solve_and_verify(s)
    profile = _single_profile(s, 0)
    return s, profile

def _cut_bore(doc, gear, p):
    marginValue = doc.param("tool_margin")
    length = doc.param("bore_tool_length")
    world = _fx.sketch_new_world()
    s, profile = _build_bore_profile(world, p, marginValue.base())
    tool = _fx.decad_extrude(doc, s, profile, _fx.decad_distance(D=length, Dir=_fx.DECAD_ALONG), name="Bore Tool Extrude", body="Bore Tool")
    cut = _fx.decad_cut(gear, tool, name="Bore Cut")
    return cut

def _chamfer_caps(gear, setback):
    selection = _fx.decad_edges(_fx.decad_outer_loop_of(_fx.decad_cap_start(gear))).or_(_fx.decad_outer_loop_of(_fx.decad_cap_end(gear)))
    chamfered = _fx.decad_chamfer(gear, selection, setback, name="Cap Chamfer")
    return chamfered

def _variant_assemble(v, r):
    disc = _build_root_disc(r)
    tooth = _variant_tooth(v, r)
    copies = _fx.decad_pattern_copies(tooth, _fx.decad_circular_pattern(Center=r.frame.origin(), Axis=r.frame.n(), Count=r.teeth), name="Tooth Pattern")
    body = _fx.decad_union(disc, *[tooth] + list(copies), name="Teeth Join")
    if not body.is_solid():
        raise RuntimeError("join teeth: result is not a solid")
    if v.RootFillet is not None:
        body = v.RootFillet(r.doc, body, r.frame)
    elif r.d.fillet > 0:
        body = _fillet_spur_roots(r.doc, body, r, r.d.base < r.d.root)
    if r.p.BoreDiameter > 0:
        body = _cut_bore(r.doc, body, r.p)
    if r.p.CapChamfer > 0:
        setback = r.doc.param("cap_chamfer")
        body = _chamfer_caps(body, setback)
    if not body.is_solid():
        raise RuntimeError("spurgear: result is not a solid")
    return body


